{"source":"import React from "react";
import { interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { palette } from "./contract";

const FONT_FAMILY = "'Archivo', sans-serif";

// Deterministic team avatars
const TEAM = [
  { name: "Alex M.", initials: "AM", color: palette.accent },
  { name: "Sarah K.", initials: "SK", color: palette.secondary },
  { name: "Dev R.", initials: "DR", color: palette.muted },
  { name: "Elena T.", initials: "ET", color: palette.foreground },
];

export const BenchmarkVideo: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // -----------------------------------------------------
  // TIMELINE SEGMENTS
  // Act 1: 0 - 90   (0s - 3s)  Intro: "Relay" & "Make room for focused work"
  // Act 2: 90 - 270 (3s - 9s)  Product: "Plan together", "Protect focus time", "See progress"
  //   - 2A: 90 - 150  (3s - 5s) "Plan together"
  //   - 2B: 150 - 210 (5s - 7s) "Protect focus time"
  //   - 2C: 210 - 270 (7s - 9s) "See progress"
  // Act 3: 270 - 360 (9s - 12s) Outro: "Start your next week with Relay" (settled by f292, static > 2s)
  // -----------------------------------------------------

  // ACT 1 ANIMATIONS (0 - 90)
  const act1Opacity = interpolate(frame, [0, 15, 76, 88], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const act1LogoSpring = spring({
    frame: frame - 6,
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  const act1TextSpring = spring({
    frame: frame - 18,
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  const act1SubSpring = spring({
    frame: frame - 28,
    fps,
    config: { damping: 14, stiffness: 90 },
  });

  // ACT 2 PRODUCT INTERFACE ANIMATIONS (90 - 270)
  const act2Opacity = interpolate(frame, [86, 96, 264, 274], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const act2Scale = interpolate(frame, [86, 110], [0.95, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Stage detection inside Act 2
  const activeStage =
    frame < 150
      ? 0 // "Plan together"
      : frame < 210
      ? 1 // "Protect focus time"
      : 2; // "See progress"

  // Stage 1 elements (Plan together)
  const card1Spring = spring({ frame: frame - 96, fps, config: { damping: 14, stiffness: 120 } });
  const card2Spring = spring({ frame: frame - 104, fps, config: { damping: 14, stiffness: 120 } });
  const card3Spring = spring({ frame: frame - 112, fps, config: { damping: 14, stiffness: 120 } });

  // Stage 2 elements (Protect focus time)
  const focusEngageSpring = spring({
    frame: frame - 152,
    fps,
    config: { damping: 12, stiffness: 100 },
  });
  const focusGlow = interpolate(
    frame,
    [150, 168, 190, 210],
    [0, 1, 0.85, 0.7],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Stage 3 elements (See progress)
  const progressCount = interpolate(frame, [212, 252], [42, 94], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const progressFill = interpolate(frame, [212, 254], [0.38, 0.94], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const metricCardsSpring = spring({
    frame: frame - 216,
    fps,
    config: { damping: 14, stiffness: 110 },
  });

  // ACT 3 OUTRO ANIMATIONS (270 - 360)
  // Settles by frame 292, static through frame 360 (68 frames = 2.26s > 2.0s readable)
  const act3Opacity = interpolate(frame, [272, 288], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const act3Spring = spring({
    frame: frame - 274,
    fps,
    config: { damping: 16, stiffness: 110 },
  });

  return (
    <div
      style={{
        width: 1920,
        height: 1080,
        backgroundColor: palette.background,
        color: palette.foreground,
        fontFamily: FONT_FAMILY,
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Subtle background grid & ambient illumination */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          backgroundImage: `radial-gradient(rgba(177, 180, 188, 0.08) 1px, transparent 1px)`,
          backgroundSize: "40px 40px",
          opacity: 0.65,
        }}
      />

      {/* Dynamic ambient background glow */}
      <div
        style={{
          position: "absolute",
          width: 900,
          height: 600,
          borderRadius: "50%",
          left: "50%",
          top: "45%",
          transform: "translate(-50%, -50%)",
          background: `radial-gradient(circle, ${
            activeStage === 1 && frame >= 90 && frame < 270
              ? "rgba(184, 243, 107, 0.12)"
              : "rgba(120, 185, 237, 0.08)"
          } 0%, transparent 70%)`,
          filter: "blur(80px)",
          pointerEvents: "none",
        }}
      />

      {/* ================================================================= */}
      {/* ACT 1: INTRO (0 - 3s)                                              */}
      {/* ================================================================= */}
      {frame < 90 && (
        <div
          style={{
            position: "absolute",
            inset: 0,
            padding: "80px 100px",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            opacity: act1Opacity,
            boxSizing: "border-box",
          }}
        >
          {/* Logo Mark */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 20,
              transform: `scale(${interpolate(act1LogoSpring, [0, 1], [0.85, 1])})`,
              opacity: act1LogoSpring,
              marginBottom: 32,
            }}
          >
            <div
              style={{
                width: 64,
                height: 64,
                borderRadius: 18,
                background: `linear-gradient(135deg, ${palette.accent} 0%, ${palette.secondary} 100%)`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxShadow: `0 12px 32px rgba(184, 243, 107, 0.25)`,
              }}
            >
              <svg width="36" height="36" viewBox="0 0 36 36" fill="none">
                <rect x="8" y="7" width="8" height="22" rx="4" fill={palette.background} />
                <rect x="20" y="11" width="8" height="18" rx="4" fill={palette.background} />
              </svg>
            </div>

            <span
              style={{
                fontSize: 68,
                fontWeight: 800,
                letterSpacing: "-0.03em",
                color: palette.foreground,
              }}
            >
              Relay
            </span>
          </div>

          {/* Headline: "Make room for focused work" */}
          <h1
            style={{
              fontSize: 62,
              fontWeight: 700,
              letterSpacing: "-0.025em",
              textAlign: "center",
              lineHeight: 1.15,
              margin: 0,
              maxWidth: 1100,
              color: palette.foreground,
              transform: `translateY(${interpolate(act1TextSpring, [0, 1], [30, 0])}px)`,
              opacity: act1TextSpring,
            }}
          >
            Make room for{" "}
            <span
              style={{
                color: palette.accent,
                borderBottom: `3px solid ${palette.accent}`,
                paddingBottom: 4,
              }}
            >
              focused work
            </span>
          </h1>

          {/* Subtle Tagline */}
          <p
            style={{
              fontSize: 22,
              fontWeight: 500,
              color: palette.muted,
              letterSpacing: "0.02em",
              marginTop: 28,
              transform: `translateY(${interpolate(act1SubSpring, [0, 1], [20, 0])}px)`,
              opacity: act1SubSpring,
            }}
          >
            The intelligent operating system for engineering and product teams
          </p>
        </div>
      )}

      {/* ================================================================= */}
      {/* ACT 2: PRODUCT INTERFACE (3s - 9s)                                 */}
      {/* "Plan together", "Protect focus time", "See progress"           */}
      {/* ================================================================= */}
      {frame >= 80 && frame <= 280 && (
        <div
          style={{
            position: "absolute",
            inset: 0,
            padding: "80px 100px",
            boxSizing: "border-box",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            opacity: act2Opacity,
            transform: `scale(${act2Scale})`,
          }}
        >
          {/* Stage Header Banner with 3 Stages */}
          <div
            style={{
              width: "100%",
              maxWidth: 1560,
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              marginBottom: 24,
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
              <div
                style={{
                  width: 32,
                  height: 32,
                  borderRadius: 10,
                  backgroundColor: palette.accent,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <svg width="18" height="18" viewBox="0 0 36 36" fill="none">
                  <rect x="8" y="7" width="8" height="22" rx="4" fill={palette.background} />
                  <rect x="20" y="11" width="8" height="18" rx="4" fill={palette.background} />
                </svg>
              </div>
              <span style={{ fontSize: 22, fontWeight: 700, color: palette.foreground }}>
                Relay
              </span>
              <span style={{ color: palette.muted, fontSize: 16 }}>/ Sprint 42</span>
            </div>

            {/* Stage Pills (Highlights current feature) */}
            <div
              style={{
                display: "flex",
                backgroundColor: "rgba(245, 245, 242, 0.05)",
                border: "1px solid rgba(177, 180, 188, 0.2)",
                borderRadius: 40,
                padding: 4,
                gap: 6,
              }}
            >
              {[ 
                { label: "Plan together", index: 0 },
                { label: "Protect focus time", index: 1 },
                { label: "See progress", index: 2 },
              ].map((pill) => {
                const isActive = activeStage === pill.index;
                return (
                  <div
                    key={pill.label}
                    style={{
                      padding: "8px 22px",
                      borderRadius: 30,
                      fontSize: 16,
                      fontWeight: isActive ? 700 : 500,
                      color: isActive ? palette.background : palette.muted,
                      backgroundColor: isActive ? palette.foreground : "transparent",
                      transition: "all 0.2s ease",
                      boxShadow: isActive ? "0 4px 14px rgba(0,0,0,0.3)" : "none",
                    }}
                  >
                    {pill.label}
                  </div>
                );
              })}
            </div>

            {/* Team live presence */}
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <div style={{ display: "flex", marginRight: 4 }}>
                {TEAM.map((member, i) => (
                  <div
                    key={member.initials}
                    style={{
                      width: 32,
                      height: 32,
                      borderRadius: "50%",
                      backgroundColor: member.color,
                      color: palette.background,
                      fontSize: 12,
                      fontWeight: 700,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      border: `2px solid ${palette.background}`,
                      marginLeft: i > 0 ? -10 : 0,
                    }}
                  >
                    {member.initials}
                  </div>
                ))}
              </div>
              <span style={{ fontSize: 14, color: palette.muted }}>4 syncing</span>
            </div>
          </div>

          {/* Main Workspace Window Card */}
          <div
            style={{
              width: "100%",
              maxWidth: 1560,
              height: 690,
              borderRadius: 20,
              backgroundColor: "rgba(20, 22, 27, 0.85)",
              border: "1px solid rgba(177, 180, 188, 0.15)",
              boxShadow: `0 30px 80px rgba(0, 0, 0, 0.7), 0 0 0 1px rgba(245, 245, 242, 0.05)`,
              display: "flex",
              flexDirection: "column",
              overflow: "hidden",
              position: "relative",
            }}
          >
            {/* Window Top Controls */}
            <div
              style={{
                height: 52,
                padding: "0 24px",
                borderBottom: "1px solid rgba(177, 180, 188, 0.1)",
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                backgroundColor: "rgba(16, 17, 20, 0.4)",
              }}
            >
              <div style={{ display: "flex", gap: 8 }}>
                <div style={{ width: 10, height: 10, borderRadius: 5, backgroundColor: "rgba(245,245,242,0.25)" }} />
                <div style={{ width: 10, height: 10, borderRadius: 5, backgroundColor: "rgba(245,245,242,0.25)" }} />
                <div style={{ width: 10, height: 10, borderRadius: 5, backgroundColor: "rgba(245,245,242,0.25)" }} />
              </div>
              <div
                style={{
                  fontSize: 14,
                  fontWeight: 600,
                  color: palette.muted,
                  letterSpacing: "0.04em",
                  textTransform: "uppercase",
                }}
              >
                {activeStage === 0 && "Stage 01 • Collaborative Schedule Alignment"}
                {activeStage === 1 && "Stage 02 • Intelligent Focus Protection Engine"}
                {activeStage === 2 && "Stage 03 • Real-Time Team Velocity & Output"}
              </div>
              <div style={{ width: 44 }} />
            </div>

            {/* STAGE 1 VIEW: PLAN TOGETHER (Frames 90 - 150) */}
            {activeStage === 0 && (
              <div
                style={{
                  flex: 1,
                  padding: 32,
                  display: "flex",
                  flexDirection: "column",
                  gap: 20,
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end" }}>
                  <div>
                    <h2
                      style={{
                        fontSize: 34,
                        fontWeight: 700,
                        margin: "0 0 6px 0",
                        color: palette.foreground,
                      }}
                    >
                      Plan together
                    </h2>
                    <p style={{ margin: 0, fontSize: 16, color: palette.muted }}>
                      Multiplayer sprint mapping with automatic conflict resolution.
                    </p>
                  </div>
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 10,
                      padding: "8px 16px",
                      borderRadius: 10,
                      backgroundColor: "rgba(120, 185, 237, 0.12)",
                      border: `1px solid ${palette.secondary}`,
                      color: palette.secondary,
                      fontSize: 14,
                      fontWeight: 600,
                    }}
                  >
                    <div style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: palette.secondary }} />
                    Auto-Syncing 12 Calendars
                  </div>
                </div>

                {/* Calendar Columns (Mon - Fri) */}
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "repeat(5, 1fr)",
                    gap: 16,
                    flex: 1,
                    marginTop: 10,
                  }}
                >
                  {[
                    {
                      day: "MON",
                      date: "14",
                      tasks: [{ title: "Sprint Alignment", time: "10:00 - 11:00", by: "AM, SK", color: palette.secondary }],
                    },
                    {
                      day: "TUE",
                      date: "15",
                      tasks: [
                        { title: "System Design Sync", time: "11:30 - 12:30", by: "ET, DR", color: palette.secondary },
                        { title: "API Contracts", time: "14:00 - 15:00", by: "AM", color: palette.muted },
                      ],
                    },
                    {
                      day: "WED",
                      date: "16",
                      tasks: [
                        { title: "Cross-Team Demo", time: "13:00 - 14:00", by: "All hands", color: palette.accent },
                      ],
                    },
                    {
                      day: "THU",
                      date: "17",
                      tasks: [{ title: "Performance Triage", time: "15:30 - 16:30", by: "SK, AM", color: palette.secondary }],
                    },
                    {
                      day: "FRI",
                      date: "18",
                      tasks: [{ title: "Release Ship Review", time: "16:00 - 17:00", by: "Team", color: palette.accent }],
                    },
                  ].map((col, idx) => (
                    <div
                      key={col.day}
                      style={{
                        backgroundColor: "rgba(16, 17, 20, 0.6)",
                        borderRadius: 14,
                        border: "1px solid rgba(177, 180, 188, 0.1)",
                        padding: 16,
                        display: "flex",
                        flexDirection: "column",
                        gap: 12,
                      }}
                    >
                      <div style={{ display: "flex", justifyContent: "space-between", color: palette.muted, fontSize: 13, fontWeight: 700 }}>
                        <span>{col.day}</span>
                        <span>{col.date}</span>
                      </div>

                      {col.tasks.map((task, tIdx) => {
                        const itemSpring = idx === 0 ? card1Spring : idx <= 2 ? card2Spring : card3Spring;
                        return (
                          <div
                            key={task.title}
                            style={{
                              backgroundColor: "rgba(245, 245, 242, 0.05)",
                              borderLeft: `4px solid ${task.color}`,
                              borderRadius: 8,
                              padding: "12px 14px",
                              transform: `translateY(${interpolate(itemSpring, [0, 1], [24 + tIdx * 10, 0])}px)`,
                              opacity: itemSpring,
                            }}
                          >
                            <div style={{ fontSize: 14, fontWeight: 600, color: palette.foreground, marginBottom: 4 }}>
                              {task.title}
                            </div>
                            <div style={{ fontSize: 12, color: palette.muted, display: "flex", justifyContent: "space-between" }}>
                              <span>{task.time}</span>
                              <span style={{ color: task.color, fontWeight: 600 }}>{task.by}</span>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* STAGE 2 VIEW: PROTECT FOCUS TIME (Frames 150 - 210) */}
            {activeStage === 1 && (
              <div
                style={{
                  flex: 1,
                  padding: 32,
                  display: "flex",
                  flexDirection: "column",
                  gap: 20,
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end" }}>
                  <div>
                    <h2
                      style={{
                        fontSize: 34,
                        fontWeight: 700,
                        margin: "0 0 6px 0",
                        color: palette.foreground,
                      }}
                    >
                      Protect focus time
                    </h2>
                    <p style={{ margin: 0, fontSize: 16, color: palette.muted }}>
                      AI blocks uninterrupted deep work windows and defends against meeting creep.
                    </p>
                  </div>
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 10,
                      padding: "8px 18px",
                      borderRadius: 10,
                      backgroundColor: `rgba(184, 243, 107, ${0.12 + focusGlow * 0.1})`,
                      border: `1px solid ${palette.accent}`,
                      color: palette.accent,
                      fontSize: 14,
                      fontWeight: 700,
                      boxShadow: `0 0 20px rgba(184, 243, 107, ${focusGlow * 0.4})`,
                    }}
                  >
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
                      <path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4zm0 10.99h7c-.53 4.12-3.28 7.79-7 8.94V12H5V6.3l7-3.11v8.8z" />
                    </svg>
                    Focus Shield Active • 14.5 hrs defended
                  </div>
                </div>

                {/* Visual Focus Shield Schedule Comparison */}
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "2fr 1fr",
                    gap: 24,
                    flex: 1,
                    marginTop: 10,
                  }}
                >
                  {/* Left Column: Protected Schedule */}
                  <div
                    style={{
                      backgroundColor: "rgba(16, 17, 20, 0.6)",
                      borderRadius: 16,
                      border: "1px solid rgba(177, 180, 188, 0.1)",
                      padding: 24,
                      display: "flex",
                      flexDirection: "column",
                      gap: 14,
                      position: "relative",
                    }}
                  >
                    <div style={{ fontSize: 14, fontWeight: 700, color: palette.muted, textTransform: "uppercase" }}>
                      Core Engineering Flow — Wednesday
                    </div>

                    {/* Diluted minor morning check-in */}
                    <div
                      style={{
                        padding: "12px 18px",
                        borderRadius: 10,
                        backgroundColor: "rgba(245, 245, 242, 0.03)",
                        border: "1px solid rgba(177, 180, 188, 0.08)",
                        color: palette.muted,
                        fontSize: 13,
                        opacity: 0.5,
                      }}
                    >
                      09:00 - 09:15 AM · Async Standup (Slack)
                    </div>

                    {/* HERO FOCUS BLOCK */}
                    <div
                      style={{
                        flex: 1,
                        borderRadius: 14,
                        backgroundColor: "rgba(184, 243, 107, 0.1)",
                        border: `2px solid ${palette.accent}`,
                        padding: 24,
                        display: "flex",
                        flexDirection: "column",
                        justifyContent: "space-between",
                        boxShadow: `0 12px 36px rgba(184, 243, 107, ${focusGlow * 0.25})`,
                        transform: `scale(${interpolate(focusEngageSpring, [0, 1], [0.97, 1])})`,
                      }}
                    >
                      <div>
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                          <span
                            style={{
                              backgroundColor: palette.accent,
                              color: palette.background,
                              fontSize: 12,
                              fontWeight: 800,
                              padding: "4px 10px",
                              borderRadius: 6,
                              letterSpacing: "0.05em",
                            }}
                          >
                            DEEP FOCUS BLOCK
                          </span>
                          <span style={{ fontSize: 14, fontWeight: 700, color: palette.accent }}>
                            09:30 AM — 01:30 PM (4h 00m)
                          </span>
                        </div>

                        <h3
                          style={{
                            fontSize: 24,
                            fontWeight: 700,
                            color: palette.foreground,
                            margin: "16px 0 8px 0",
                          }}
                        >
                          Distributed Consensus & Sharding Logic
                        </h3>
                        <p style={{ margin: 0, fontSize: 14, color: palette.muted }}>
                          All non-urgent pings suppressed. Teammates informed: In Deep Focus.
                        </p>
                      </div>

                      <div
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: 16,
                          borderTop: "1px solid rgba(184, 243, 107, 0.2)",
                          paddingTop: 14,
                        }}
                      >
                        <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, color: palette.foreground }}>
                          <div style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: palette.accent }} />
                          Auto-declined: 2 conflicting meetings
                        </div>
                        <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, color: palette.secondary }}>
                          <div style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: palette.secondary }} />
                          Deep work target reached: 100%
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Right Column: Focus Stats Card */}
                  <div
                    style={{
                      backgroundColor: "rgba(16, 17, 20, 0.6)",
                      borderRadius: 16,
                      border: "1px solid rgba(177, 180, 188, 0.1)",
                      padding: 24,
                      display: "flex",
                      flexDirection: "column",
                      justifyContent: "space-around",
                    }}
                  >
                    <div>
                      <div style={{ fontSize: 14, color: palette.muted, marginBottom: 6 }}>Focus Hours Gained</div>
                      <div style={{ fontSize: 44, fontWeight: 800, color: palette.accent, letterSpacing: "-0.02em" }}>
                        +6.5 hrs
                      </div>
                      <div style={{ fontSize: 13, color: palette.muted, marginTop: 4 }}>per engineer / week</div>
                    </div>

                    <div style={{ borderTop: "1px solid rgba(177, 180, 188, 0.1)", paddingTop: 16 }}>
                      <div style={{ fontSize: 14, color: palette.muted, marginBottom: 6 }}>Interruption Rate</div>
                      <div style={{ fontSize: 36, fontWeight: 800, color: palette.secondary }}>
                        -74%
                      </div>
                      <div style={{ fontSize: 13, color: palette.muted, marginTop: 4 }}>context switches eliminated</div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* STAGE 3 VIEW: SEE PROGRESS (Frames 210 - 270) */}
            {activeStage === 2 && (
              <div
                style={{
                  flex: 1,
                  padding: 32,
                  display: "flex",
                  flexDirection: "column",
                  gap: 20,
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end" }}>
                  <div>
                    <h2
